"""Tests for office-inspect. Every file here is generated by the test itself from nothing but the
standard library: no fixture is copied from anywhere, and every text in them is invented."""

import importlib.util
import io
import json
import os
import re
import subprocess
import sys
import zipfile
from pathlib import Path

import pytest

TOOL = Path(__file__).resolve().parent.parent / "office_inspect.py"
spec = importlib.util.spec_from_file_location("office_inspect", TOOL)
oi = importlib.util.module_from_spec(spec)
spec.loader.exec_module(oi)

W = "http://schemas.openxmlformats.org/wordprocessingml/2006/main"
S = "http://schemas.openxmlformats.org/spreadsheetml/2006/main"
R = "http://schemas.openxmlformats.org/officeDocument/2006/relationships"
P = "http://schemas.openxmlformats.org/presentationml/2006/main"
PKG_REL = "http://schemas.openxmlformats.org/package/2006/relationships"


def content_types(main):
    return (
        '<?xml version="1.0" encoding="UTF-8"?>'
        '<Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types">'
        f'<Override PartName="/x" ContentType="{main}"/></Types>'
    )


DOCX_CT = content_types("application/vnd.openxmlformats-officedocument.wordprocessingml.document.main+xml")
XLSX_CT = content_types("application/vnd.openxmlformats-officedocument.spreadsheetml.sheet.main+xml")
PPTX_CT = content_types("application/vnd.openxmlformats-officedocument.presentationml.presentation.main+xml")


def make_zip(path, parts):
    with zipfile.ZipFile(path, "w", zipfile.ZIP_DEFLATED) as zf:
        for name, data in parts.items():
            zf.writestr(name, data)
    return path


def docx_parts(extra=None, body=None):
    body = body or (
        f'<w:p><w:pPr><w:pStyle w:val="Heading1"/></w:pPr><w:r><w:t>Title</w:t></w:r></w:p>'
        f'<w:p><w:pPr><w:pStyle w:val="Heading2"/></w:pPr><w:r><w:t>Part</w:t></w:r></w:p>'
        f"<w:p><w:r><w:t>Text</w:t></w:r></w:p><w:tbl><w:tr><w:tc><w:p/></w:tc></w:tr></w:tbl>"
    )
    parts = {
        "[Content_Types].xml": DOCX_CT,
        "word/document.xml": f'<?xml version="1.0"?><w:document xmlns:w="{W}"><w:body>{body}</w:body></w:document>',
    }
    parts.update(extra or {})
    return parts


def xlsx_parts(sheet_xml, extra=None):
    parts = {
        "[Content_Types].xml": XLSX_CT,
        "xl/workbook.xml": f'<?xml version="1.0"?><workbook xmlns="{S}" xmlns:r="{R}"><sheets>'
        '<sheet name="Invoices" sheetId="1" r:id="rId1"/></sheets></workbook>',
        "xl/_rels/workbook.xml.rels": f'<?xml version="1.0"?><Relationships xmlns="{PKG_REL}">'
        '<Relationship Id="rId1" Type="x/worksheet" Target="worksheets/sheet1.xml"/></Relationships>',
        "xl/worksheets/sheet1.xml": sheet_xml,
    }
    parts.update(extra or {})
    return parts


def sheet(cells, dim="A1:B3"):
    return f'<?xml version="1.0"?><worksheet xmlns="{S}"><dimension ref="{dim}"/><sheetData>{cells}</sheetData></worksheet>'


def run(path):
    """Run the real command line, as the member's computer does, and return (exit code, JSON)."""
    proc = subprocess.run([sys.executable, "-I", str(TOOL), str(path)], capture_output=True, text=True, timeout=60)
    return proc.returncode, (json.loads(proc.stdout) if proc.stdout.strip() else None), proc.stderr


def test_a_word_file_is_counted_from_its_bytes(tmp_path):
    f = make_zip(tmp_path / "letter.docx", docx_parts({"word/media/a.png": b"x"}))
    code, out, _ = run(f)
    assert code == 0 and out["detected_type"] == "docx"
    assert out["size_bytes"] == f.stat().st_size
    d = out["docx"]
    assert (d["paragraphs"], d["tables"], d["images"]) == (4, 1, 1)
    assert d["headings_by_level"] == {"1": 1, "2": 1}
    assert out["macros"]["present"] is False and out["refused"] is False


def test_the_type_is_detected_from_the_bytes_not_the_name(tmp_path):
    f = make_zip(tmp_path / "budget.pdf", xlsx_parts(sheet('<row r="1"><c r="A1"><v>1</v></c></row>')))
    code, out, _ = run(f)
    assert code == 0 and out["detected_type"] == "xlsx"
    assert out["extension"] == ".pdf" and out["extension_matches_content"] is False
    pdf = tmp_path / "scan.docx"
    pdf.write_bytes(minimal_pdf(2))
    code, out, _ = run(pdf)
    assert code == 0 and out["detected_type"] == "pdf" and out["extension_matches_content"] is False
    assert out["pdf"]["pages"] == 2


def test_formulas_are_counted_and_never_evaluated(tmp_path):
    cells = (
        '<row r="1"><c r="A1"><v>2</v></c><c r="B1"><f>A1*100</f></c></row>'
        '<row r="2"><c r="A2"><v>3</v></c><c r="B2"><f>SUM(A1:A2)</f><v>999</v></c></row>'
        '<row r="3"><c r="B3"><f>1/0</f></c></row>'
    )
    f = make_zip(tmp_path / "t.xlsx", xlsx_parts(sheet(cells)))
    code, out, _ = run(f)
    assert code == 0
    x = out["xlsx"]
    assert x["sheet_count"] == 1 and x["formulas_total"] == 3
    s = x["sheets"][0]
    assert s["name"] == "Invoices" and s["used_range"] == "A1:B3" and s["declared_dimension"] == "A1:B3"
    # B2 carries a stored value (999, which is wrong on purpose: it is reported as stored, never recomputed);
    # B1 and B3 have none, and 1/0 raised nothing because nothing is evaluated.
    assert s["formulas"] == 3 and s["formulas_without_stored_value"] == 2


def test_formulas_that_reach_outside_are_reported_by_kind(tmp_path):
    cells = (
        '<row r="1"><c r="A1"><f>WEBSERVICE("http://example.test/x")</f></c></row>'
        "<row r=\"2\"><c r=\"A2\"><f>cmd|'/c calc'!A1</f></c></row>"
    )
    f = make_zip(tmp_path / "t.xlsx", xlsx_parts(sheet(cells, "A1:A2")))
    code, out, _ = run(f)
    assert code == 0
    assert out["xlsx"]["formula_patterns_reported"] == {"webservice": 1, "dde": 1}


def test_external_links_are_reported_and_never_fetched(tmp_path):
    rels = (
        f'<?xml version="1.0"?><Relationships xmlns="{PKG_REL}">'
        '<Relationship Id="r1" Type="x/hyperlink" Target="http://example.test/a" TargetMode="External"/>'
        '<Relationship Id="r2" Type="x/oleObject" Target="file:///nowhere/x" TargetMode="External"/></Relationships>'
    )
    f = make_zip(tmp_path / "t.docx", docx_parts({"word/_rels/document.xml.rels": rels}))
    code, out, _ = run(f)
    links = out["external_links"]
    assert code == 0 and links["present"] is True
    assert (links["hyperlinks"], links["other_external_targets"]) == (1, 1)
    assert links["samples"][0]["target"] == "http://example.test/a"


def test_a_presentation_is_counted(tmp_path):
    parts = {
        "[Content_Types].xml": PPTX_CT,
        "ppt/presentation.xml": f'<p:presentation xmlns:p="{P}" xmlns:r="{R}"><p:sldIdLst>'
        '<p:sldId id="256" r:id="a"/><p:sldId id="257" r:id="b"/></p:sldIdLst></p:presentation>',
        "ppt/slides/slide1.xml": "<a/>",
        "ppt/slides/slide2.xml": "<a/>",
        "ppt/notesSlides/notesSlide1.xml": "<a/>",
    }
    code, out, _ = run(make_zip(tmp_path / "d.pptx", parts))
    assert code == 0 and out["pptx"]["slides"] == 2 and out["pptx"]["notes_slides"] == 1


# ---- refusals ----------------------------------------------------------------------------------


def test_a_macro_project_is_refused_whatever_the_name(tmp_path):
    f = make_zip(tmp_path / "innocent.xlsx", xlsx_parts(sheet(""), {"xl/vbaProject.bin": b"\x00\x01"}))
    code, out, _ = run(f)
    assert code == 3 and out["refused"] is True and out["reason_code"] == "macros"
    assert "macros" in out["reason"] and "xl/vbaProject.bin" in out["macro_evidence"]
    assert "xlsx" not in out


def test_a_macro_enabled_content_type_is_refused(tmp_path):
    ct = content_types("application/vnd.ms-word.document.macroEnabled.main+xml")
    f = make_zip(tmp_path / "x.docx", {"[Content_Types].xml": ct, "word/document.xml": "<a/>"})
    code, out, _ = run(f)
    assert code == 3 and out["reason_code"] == "macros"


@pytest.mark.parametrize("ext", [".docm", ".xlsm", ".pptm"])
def test_macro_extensions_are_refused_with_a_sentence(tmp_path, ext):
    f = make_zip(tmp_path / ("x" + ext), docx_parts())
    code, out, _ = run(f)
    assert code == 3 and out["reason_code"] == "macro_extension"
    assert "without macros" in out["reason"]


@pytest.mark.parametrize("ext", [".doc", ".xls", ".ppt"])
def test_old_binary_formats_are_refused_by_their_bytes(tmp_path, ext):
    f = tmp_path / ("old" + ext)
    f.write_bytes(oi.OLE_MAGIC + b"\x00" * 600)
    code, out, _ = run(f)
    assert code == 3 and out["reason_code"] == "legacy_binary"
    assert ".docx, .xlsx or .pptx" in out["reason"]
    renamed = tmp_path / "renamed.docx"
    renamed.write_bytes(oi.OLE_MAGIC + b"\x00" * 600)
    code, out, _ = run(renamed)
    assert code == 3 and out["reason_code"] == "legacy_binary"


def test_unknown_bytes_and_empty_files_are_refused(tmp_path):
    a = tmp_path / "a.docx"
    a.write_text("just text")
    assert run(a)[1]["reason_code"] == "unknown_type"
    b = tmp_path / "b.xlsx"
    b.write_bytes(b"")
    assert run(b)[1]["reason_code"] == "empty"


def test_a_zip_bomb_is_refused_from_its_directory_before_anything_is_read(tmp_path):
    # 5 MiB of zeros stores in about 5 KiB: a ratio far over 100 to 1.
    f = make_zip(tmp_path / "bomb.xlsx", xlsx_parts(sheet(""), {"xl/media/zeros.bin": b"\x00" * (5 * 1024 * 1024)}))
    code, out, _ = run(f)
    assert code == 3 and out["reason_code"] == "zip_bomb_ratio"
    # One part declaring more than the 100 MiB per-entry limit.
    big = make_zip(tmp_path / "big.docx", docx_parts({"word/media/z.bin": b"\x00" * (101 * 1024 * 1024)}))
    code, out, _ = run(big)
    assert code == 3 and out["reason_code"] in ("entry_too_large", "zip_bomb_ratio")


def test_too_many_entries_are_refused(tmp_path):
    parts = docx_parts()
    for i in range(oi.MAX_ENTRIES + 1):
        parts[f"word/media/{i}.txt"] = b""
    code, out, _ = run(make_zip(tmp_path / "many.docx", parts))
    assert code == 3 and out["reason_code"] == "too_many_entries"


def test_the_total_expanded_size_is_limited(tmp_path, monkeypatch):
    monkeypatch.setattr(oi, "MAX_TOTAL_UNCOMPRESSED", 3000)
    f = make_zip(tmp_path / "t.docx", docx_parts({"word/media/a.bin": os.urandom(4000)}))
    with pytest.raises(oi.Refused) as caught:
        oi.inspect(str(f))
    assert caught.value.extra["reason_code"] == "archive_too_large"


@pytest.mark.parametrize("name", ["../evil.xml", "/etc/passwd", "word\\..\\x.xml", "word/../../x"])
def test_entry_names_that_leave_the_archive_are_refused(tmp_path, name):
    f = make_zip(tmp_path / "p.docx", docx_parts({name: b"x"}))
    code, out, _ = run(f)
    assert code == 3 and out["reason_code"] == "unsafe_entry_name"


def laughs():
    lines = ['<!ENTITY a0 "lol">'] + [
        f'<!ENTITY a{i} "&a{i-1};&a{i-1};&a{i-1};&a{i-1};&a{i-1};&a{i-1};&a{i-1};&a{i-1};&a{i-1};&a{i-1};">'
        for i in range(1, 10)
    ]
    return "<!DOCTYPE lolz [" + "".join(lines) + "]>"


def test_an_xml_entity_bomb_is_refused_and_not_expanded(tmp_path):
    body = f'<?xml version="1.0"?>{laughs()}<worksheet xmlns="{S}"><sheetData><row r="1"><c r="A1" t="inlineStr"><is><t>&a9;</t></is></c></row></sheetData></worksheet>'
    f = make_zip(tmp_path / "lol.xlsx", xlsx_parts(body))
    import resource

    before = resource.getrusage(resource.RUSAGE_SELF).ru_maxrss
    with pytest.raises(oi.Refused) as caught:
        oi.inspect(str(f))
    after = resource.getrusage(resource.RUSAGE_SELF).ru_maxrss
    assert caught.value.extra["reason_code"] == "xml_dtd"
    assert after - before < 50_000  # kilobytes: a ten-level bomb would be gigabytes
    code, out, _ = run(f)
    assert code == 3 and out["reason_code"] == "xml_dtd"


def test_an_external_entity_is_refused_and_no_file_is_read(tmp_path):
    secret = tmp_path / "secret.txt"
    secret.write_text("TOP-SECRET-MARKER")
    dtd = f'<!DOCTYPE d [<!ENTITY xxe SYSTEM "file://{secret}">]>'
    body = f'<?xml version="1.0"?>{dtd}<w:document xmlns:w="{W}"><w:body><w:p><w:r><w:t>&xxe;</w:t></w:r></w:p></w:body></w:document>'
    f = make_zip(tmp_path / "xxe.docx", {"[Content_Types].xml": DOCX_CT, "word/document.xml": body})
    code, out, _ = run(f)
    assert code == 3 and out["reason_code"] == "xml_dtd"
    assert "TOP-SECRET-MARKER" not in json.dumps(out)


