def test_the_cell_limit_stops_a_big_sheet(tmp_path, monkeypatch):
    monkeypatch.setattr(oi, "MAX_CELLS", 3)
    cells = "".join(f'<row r="{i}"><c r="A{i}"><v>1</v></c></row>' for i in range(1, 8))
    f = make_zip(tmp_path / "t.xlsx", xlsx_parts(sheet(cells, "A1:A7")))
